const body = $input.first().json.body || $input.first().json;

const candidatNom       = body.candidat_nom       || '';
const candidatEmail     = body.candidat_email      || '';
const candidatTelephone = body.candidat_telephone  || '';
const canalCandidature  = body.canal_candidature   || 'plateforme';
const aEmail            = !!candidatEmail;
const aAppeler          = !candidatEmail;

const offreId             = body.offre_id             || '';
const titrePoste          = body.titre_poste          || '';
const emailRecruteur      = body.email_recruteur      || '';
const descriptionPoste    = body.description_poste    || '';
const competences         = body.competences_requises || '';
const annees              = body.annees_experience    || '';
const langues             = body.langues_requises     || '';
const exigencesIa         = body.exigences_ia         || '';
const profilSouhaite      = body.profil_souhaite      || '';

const cvFilename     = body.cv_filename     || '';
const cvPath         = body.cv_path         || '';
const cvBase64       = body.cv_base64       || '';
const cvMimetype     = body.cv_mimetype     || 'application/pdf';
const lettreFilename = body.lettre_filename || '';
const lettrePath     = body.lettre_path     || '';

const baseUrl        = body.base_url        || 'http://localhost:3000';
const callbackSecret = body.callback_secret || '';

if (!offreId)     throw new Error('offre_id manquant dans le payload');
if (!candidatNom) throw new Error('candidat_nom manquant dans le payload');

return [{
  json: {
    candidatNom, candidatEmail, candidatTelephone, canalCandidature,
    aEmail, aAppeler,
    offreId, titrePoste, emailRecruteur,
    descriptionPoste, competences, annees, langues, exigencesIa, profilSouhaite,
    cvFilename, cvPath, cvBase64, cvMimetype,
    lettreFilename, lettrePath,
    baseUrl, callbackSecret,
    company: body.company || 'solumada',
    hasCv: cvBase64 !== '',
  }
}];

const prev      = $('Extract and Validate Data').first().json;
const insertedId = $('Create Application in MongoDB').first().json.insertedId
               || $('Create Application in MongoDB').first().json._id
               || '';

const cvTexte = '(CV en cours d\'extraction — traitement via binaire non disponible dans ce nœud)'
// Note : si vous avez le nœud Extract From File, branchez-le avant ce nœud
// pour extraire le texte du CV base64 et remplacez cvTexte par son output.

const systemPrompt = `Tu es un expert RH senior spécialisé dans le recrutement à Madagascar. Tu analyses des candidatures de manière objective et professionnelle. Tu fournis des analyses structurées et précises en JSON.`;

const userPrompt = `Analyse cette candidature pour le poste de "${prev.titrePoste}" et retourne un JSON structuré.

## Fiche de poste
- **Titre** : ${prev.titrePoste}
- **Expérience requise** : ${prev.annees || 'Non précisé'}
- **Compétences requises** : ${prev.competences}
- **Langues requises** : ${prev.langues || 'Non précisé'}
- **Profil souhaité** : ${prev.profilSouhaite || 'Non précisé'}
- **Description** : ${prev.descriptionPoste}
${prev.exigencesIa ? `- **Exigences spéciales IA** : ${prev.exigencesIa}` : ''}

## CV du candidat : ${prev.candidatNom}
---
${cvTexte}
---

## Instructions importantes
Retourne UNIQUEMENT un objet JSON valide, sans markdown ni commentaire. Structure exacte :

{
  "score": <entier 0-10>,
  "recommandation": <"QUALIFIE" | "A_REVOIR" | "NON_SELECTIONNE">,
  "resume_analyse": "<Résumé de 2-3 phrases>",
  "adequation_poste": "<Évaluation adéquation profil/poste en 1-2 phrases>",
  "competences_detectees": "<Liste séparée par virgules>",
  "competences_manquantes": "<Liste séparée par virgules>",
  "experience_annees": <nombre entier ou null>,
  "niveau_education": "<Bac, Licence, Master, Doctorat, CAP, etc.>",
  "points_forts": "<3 points forts max, séparés par tirets>",
  "points_faibles": "<3 points faibles max, séparés par tirets>"
}

## Barème
- 8-10 : Profil excellent → QUALIFIE
- 5-7  : Profil intéressant → A_REVOIR
- 0-4  : Profil insuffisant → NON_SELECTIONNE
${prev.exigencesIa ? '\n⚠️ Critères éliminatoires non remplis → score ≤ 3 et NON_SELECTIONNE.' : ''}`;

const isEn = (prev.company || 'solumada') === 'optimum';
if (isEn) {
  userPrompt += '\n\nIMPORTANT: All text fields in your JSON response MUST be in English (resume_analyse, adequation_poste, points_forts, points_faibles, competences_detectees, competences_manquantes).';
}

return [{
  json: {
    ...prev,
    insertedId,
    cvTexte,
    systemPrompt,
    userPrompt,
  }
}];

const claudeResponse = $input.first().json;
const prev = $('Build Claude Prompt').first().json;

let rawText = '';
try {
  rawText = claudeResponse.content?.[0]?.text || '';
} catch(e) {
  throw new Error('Structure réponse Claude invalide');
}

if (!rawText) throw new Error('Réponse Claude vide');

const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (!jsonMatch) throw new Error('Aucun JSON dans la réponse Claude');

let analyse;
try {
  analyse = JSON.parse(jsonMatch[0]);
} catch(e) {
  throw new Error('JSON Claude non parseable');
}

const score = Math.min(10, Math.max(0, parseInt(analyse.score) || 0));
const valid = ['QUALIFIE', 'A_REVOIR', 'NON_SELECTIONNE'];
let recommandation = (analyse.recommandation || '').toUpperCase().replace('-', '_');
if (!valid.includes(recommandation)) {
  recommandation = score >= 8 ? 'QUALIFIE' : score >= 5 ? 'A_REVOIR' : 'NON_SELECTIONNE';
}

console.log(`[WF3] Analyse terminée pour ${prev.candidatNom} — Score: ${score}/10 — ${recommandation}`);

return [{
  json: {
    insertedId:             prev.insertedId,
    score,
    recommandation,
    resume_analyse:         String(analyse.resume_analyse         || ''),
    adequation_poste:       String(analyse.adequation_poste       || ''),
    competences_detectees:  String(analyse.competences_detectees  || ''),
    competences_manquantes: String(analyse.competences_manquantes || ''),
    experience_annees:      analyse.experience_annees != null ? Number(analyse.experience_annees) : null,
    niveau_education:       String(analyse.niveau_education       || ''),
    points_forts:           String(analyse.points_forts           || ''),
    points_faibles:         String(analyse.points_faibles         || ''),
  }
}];

